import React, { useState, useRef, useEffect } from "react";

import { DateRange } from "react-date-range";
import { enUS } from "date-fns/locale";
import "react-date-range/dist/styles.css";
import "react-date-range/dist/theme/default.css";
import { FaCalendarAlt } from "react-icons/fa"; // Calendar icon

import DataTable from "react-data-table-component";
import { makeApiRequest } from "../axiosService/ApiCall";
import { Spinner } from "react-bootstrap";
import { toast } from "react-toastify";
import eth from "../Assets/images/ethereum.png";
import usdt from "../Assets/images/usdt.png";
import btc from "../Assets/images/btc.png";
import sol from "../Assets/images/solana.png";
import ltc from "../Assets/images/litecoin.png";
import car from "../Assets/images/cardano.png";
import Select from "react-select";
import { MdRefresh } from "react-icons/md";

const cryptoData = [
  { img: eth, textOne: "ETH", textTwo: "Ethereum" },
  { img: usdt, textOne: "USDT", textTwo: "Tether USDT" },
  { img: btc, textOne: "BTC", textTwo: "Bitcoin" },
  { img: sol, textOne: "SOL", textTwo: "Solana" },
  { img: ltc, textOne: "LTC", textTwo: "Litecoin" },
  { img: car, textOne: "ADA", textTwo: "Cardano" },
];

function SwapHistory() {
  const [loading, setLoading] = useState(true);
  const [swapData, setSwapData] = useState([]);
  const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [selectfromCoin, setSelectFromCoin] = useState("");
  const [selecttoCoin, setSelectToCoin] = useState("");
  const [totalPages, setTotalPages] = useState(0);
  const [limit, setLimit] = useState(10);
  const [fromDate, setFromDate] = useState("");
  const [selectedSymbol, setSelectedSymbol] = useState("");
  const [toDate, setToDate] = useState("");
  const [showCalendar, setShowCalendar] = useState(false);
  const [totalItems, setTotalItems] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [is_Refreshing, setIs_Refreshing] = useState(false);
  const [resetPaginationToggle, setResetPaginationToggle] = useState(false);
  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: "selection",
    },
  ]);
  const calendarRef = useRef(null);

  useEffect(() => {
    getData(currentPage, search);
  }, [selectfromCoin, selecttoCoin, currentPage, search, fromDate, toDate, limit]);

  const getData = async (page = 1) => {
    try {
      let queryParams = new URLSearchParams({
        fromCoin: selectfromCoin || "",
        toCoin: selecttoCoin || "",
        search: search || "",
        fromDate: fromDate || "",
        toDate: toDate || "",
        page: page,
        limit: limit,
      }).toString();
      let params = {
        url: `user-swapHistory?${queryParams}`,
        method: "GET",
      };
      const response = await makeApiRequest(params);
      // console.log('response=--=', response)
      if (response.status) {
        setSwapData(response.data);
        setLoading(false);
        setTotalPages(response.totalPages);
        setTotalItems(response.totalItems)
      } else {
        setSwapData([]);
        setLoading(false);
        setTotalPages(0);
        setTotalItems(0)
      }
    } catch (error) {
      toast("Internal Error in Swap Data");
      setLoading(false);
    }
  };

  const handleChange = (selectedOption) => {
    handleReset()
    setSelectFromCoin(selectedOption ? selectedOption.value : "");
  };

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (calendarRef.current && !calendarRef.current.contains(event.target)) {
        setShowCalendar(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const cryptoFromCoin = cryptoData.map((data) => ({
    value: data.textOne,
    label: (
      <div style={{ display: "flex", alignItems: "center" }}>
        <img
          src={data.img}
          alt={data.textOne}
          style={{ width: 20, height: 20, marginRight: 10 }}
        />
        {data.textOne}
      </div>
    ),
  }));

  const handleClickChange = (selectedOption) => {
    handleReset()
    setSelectToCoin(selectedOption ? selectedOption.value : "");
  };


  const cryptoToCoin = cryptoData.map((data) => ({
    value: data.textOne,
    label: (
      <div style={{ display: "flex", alignItems: "center" }}>
        <img
          src={data.img}
          alt={data.textOne}
          style={{ width: 20, height: 20, marginRight: 10 }}
        />
        {data.textOne}
      </div>
    ),
  }));

  const handleClearFilters = async () => {
    setIsRefreshing(true);
    setSearch("");
    setSelectFromCoin("");
    setIs_Refreshing(is_Refreshing ? false : true);
    setSelectToCoin("")
    setFromDate("");
    setToDate("");
    setRange([
      {
        startDate: new Date(),
        endDate: new Date(),
        key: "selection",
      },
    ]);
    setCurrentPage(1);
    setLimit(10);

    getData(1);

    const start = Date.now();

    const elapsed = Date.now() - start;
    if (elapsed < 500) {
      // ensure at least 500ms rotation
      await new Promise(resolve => setTimeout(resolve, 500 - elapsed));
    }


    setIsRefreshing(false); // Stop spinning
  };

  const dateFormat = (date) => {
    try {
      const orgDate = new Date(date).toUTCString();
      // console.log('orgDate', orgDate)
      const hours = new Date(date).getUTCHours();
      const amOrPm = hours >= 12 ? "PM" : "AM";
      const formattedDate = orgDate.split(",")[1].split("GMT")[0] + amOrPm;
      return formattedDate;
    } catch (e) {
      return "Invalid Date Format";
    }
  };

  const columnsone = [
    {
      name: "S.No",
      selector: (row, index) => (currentPage - 1) * limit + index + 1,
      sortable: true,
      width: "75px",
    },
    {
      name: "Email",
      selector: (row) => row.email,
      sortable: true,
      width: "250px",
    },
    {
      name: "From Currency",
      selector: (row) => row.fromCoin,
      sortable: true,
      width: "130px",
    },
    {
      name: "To Currency",
      selector: (row) => row.toCoin,
      sortable: true,
      width: "130px",
    },
    {
      name: "From Amount",
      selector: (row) => userpower(formatWithoutRounding(userpower(row.fromAmount), 4)) || "--",
      sortable: true,
      width: "130px",
    },
    {
      name: "To Amount",
      selector: (row) => userpower(formatWithoutRounding(userpower(row.toAmount), 10)) || "--",
      sortable: true,
    },
    {
      name: "Receive Amount",
      selector: (row) => userpower(formatWithoutRounding(userpower(row.receiveAmount), 10)),
      sortable: true,
      width: "200px",
    },
    {
      name: "Fee Amount",
      selector: (row) => `${userpower(formatWithoutRounding(userpower(row.feeAmount), 10)) + "  " + (row.toCoin)}` || "--",
      sortable: true,
      width: "250px",
    },
    {
      name: "Date(UTC)",
      selector: (row) => dateFormat(row.createdAt),
      sortable: true,
      width: "250px",
    },
  ];

  const handleReset = async () => {
    setLimit(10);
    setCurrentPage(1);
    setResetPaginationToggle(!resetPaginationToggle);
  }

  const handleSearchChange = (e) => {
    setSearch(e.target.value);
    handleReset()
  };

  const formatWithoutRounding = (value, decimals) => {
    const factor = Math.pow(10, decimals);
    return Math.floor(value * factor) / factor;
  };

  const userpower = (x) => {
    x = x.toString();

    if (x.includes('e-')) {
      const [num, exp] = x.split('e-');
      const e = parseInt(exp);
      const digits = num.replace('.', '');
      const result = '0.' + '0'.repeat(e - 1) + digits;
      return result;
    } else if (x.includes('e+')) {
      const [num, exp] = x.split('e+');
      const e = parseInt(exp);
      const [intPart, decPart = ''] = num.split('.');
      let fullNum = intPart + decPart;
      while (fullNum.length < intPart.length + e) {
        fullNum += '0';
      }
      const decimal = fullNum.slice(0, intPart.length + e) + '.' + fullNum.slice(intPart.length + e);
      return decimal;
    }

    return x;
  }

  const handleDateChange = (item) => {

    setRange([item.selection]);

    const formatDate = (date) => {
      return date.toLocaleDateString("en-CA");
    };

    setFromDate(formatDate(item.selection.startDate));
    setToDate(formatDate(item.selection.endDate));
    setCurrentPage(1);
  };

  const customStyles = {
    control: (base, state) => ({
      ...base,
      borderColor: state.isFocused ? "var(--color-1)" : "var(--color-1)",
      boxShadow: state.isFocused ? "0 0 0 1px var(--color-1)" : "none",
      borderRadius: "8px",
      fontSize: "13px",
      "&:hover": {
        borderColor: "var(--color-1)",
      },
      minWidth: "140px",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: "8px",
      marginTop: 4,
    }),
    singleValue: (base) => ({
      ...base,
      color: "#000",
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isSelected
        ? "var(--color-1)"
        : state.isFocused
          ? "#58f9b07c"
          : "white",
      color: state.isSelected ? "var(--theme-text-1)" : "black",
      ":active": {
        backgroundColor: "var(--color-1)",
      },
      cursor: "pointer",
      fontSize: "13px",
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 9999,
    }),
  };

  return (
    <div className="App">
      <div className="container-fluid " >
        <div className=" text-dark">
          <div className="row">
            <div className="col-lg-12">
              <div className="py-3 justify-content-center d-flex justify-content-between">
                <h3 className="component-user text-center ms-lg-0">
                  Swap History
                </h3>
              </div>
              <div className="d-flex calendor-form align-items-end">
                <form className="d-flex gap-lg-2 align-items-end flex-wrap">
                  <div className="mb-3">
                    <label for="email" className="form-label">
                      Email
                    </label>
                    <input
                      type="text"
                      className="form-control search-bar"
                      name="email"
                      id="email"
                      aria-describedby="emailHelp"
                      placeholder="email"
                      value={search}
                      onChange={handleSearchChange}
                      style={{ width: "220px" }}
                    />
                  </div>
                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      From Coin
                    </label>
                    <Select
                      options={cryptoFromCoin}
                      value={
                        selectfromCoin
                          ? cryptoFromCoin.find((option) => option.value === selectfromCoin)
                          : null
                      }
                      onChange={handleChange}
                      id="border-css"
                      isClearable
                      styles={customStyles}
                      isSearchable={false}
                      components={{
                        IndicatorSeparator: () => null,
                      }}
                    />
                  </div>
                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      To Coin
                    </label>
                    <Select
                      options={cryptoToCoin}
                      value={
                        selecttoCoin
                          ? cryptoToCoin.find((option) => option.value === selecttoCoin)
                          : null
                      }
                      onChange={handleClickChange}
                      id="border-css"
                      isClearable
                      styles={customStyles}
                      isSearchable={false}
                      components={{
                        IndicatorSeparator: () => null,
                      }}
                    />
                  </div>
                  <div className="mb-3">
                    <label for="exampleInputPassword1" className="form-label">
                      Date
                    </label>

                    <div
                      ref={calendarRef}
                      style={{ position: "relative", width: "250px" }}
                    >
                      <div
                        onClick={() => { setShowCalendar(!showCalendar); handleReset() }}
                        style={{
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "space-between",
                          padding: "6px",
                          border: "1px solid var(--color-1)",
                          borderRadius: "5px",
                          cursor: "pointer",
                          backgroundColor: "#fff",
                          fontSize: "14px",
                        }}
                      >
                        <span>
                          {fromDate && toDate
                            ? `${fromDate} - ${toDate}`
                            : "Select Date Range"}
                        </span>
                        <FaCalendarAlt style={{ color: "#555" }} />
                      </div>
                      {showCalendar && (
                        <div
                          style={{
                            position: "absolute",
                            top: "100%",
                            left: -80,
                            zIndex: 1000,
                            background: "#fff",
                            boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                            borderRadius: "5px",
                          }}
                        >
                          <DateRange
                            editableDateInputs={true}
                            onChange={handleDateChange}
                            moveRangeOnFirstSelection={false}
                            ranges={range}
                            locale={enUS}
                            rangeColors={["#58f9b0"]}
                          />
                        </div>
                      )}
                    </div>
                  </div>
                  <div className="mb-2">
                    <button
                      type="button"
                      className="form-label custom-nav-button-1 active cursor-pointer"
                      onClick={handleClearFilters}
                      disabled={isRefreshing}
                    >
                      <MdRefresh
                        style={{ fontSize: "24px" }}
                        className={isRefreshing ? "rotate-icon" : ""}
                      />
                    </button>
                  </div>
                </form>
              </div>

              <div className="liquidity-table-1">
                <DataTable
                  key={is_Refreshing}
                  columns={columnsone}
                  data={swapData}
                  theme="solarized"
                  defaultSortAsc={true}
                  pagination
                  paginationServer
                  persistTableHead
                  paginationPerPage={limit}
                  paginationTotalRows={totalItems}
                  paginationRowsPerPageOptions={[5, 10, 15]}
                  paginationResetDefaultPage={resetPaginationToggle}
                  onChangeRowsPerPage={(newRowsPerPage) => {
                    setLimit(newRowsPerPage);
                    setCurrentPage(1);
                  }}
                  onChangePage={(page) => setCurrentPage(page)}
                  progressPending={loading}
                  progressComponent={
                    <div className="py-4 w-100" style={{ marginLeft: "45vw" }}>
                      <Spinner animation="border" />
                    </div>
                  }
                />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default SwapHistory;
